SELECT w.*,o.phase AS owner_phase,o.held_rows AS owner_held_rows,o.held_bytes AS owner_held_bytes,o.peak_rows AS owner_peak_rows,o.peak_bytes AS owner_peak_bytes,o.removed_rows AS owner_removed_rows,o.removed_bytes AS owner_removed_bytes FROM {s}.init_operation o LEFT JOIN LATERAL (SELECT 1 AS present,canonical_position,aliases,file_root FROM {s}.init_host_file WHERE operation_id=$1::bigint AND canonical_position>$3::bigint ORDER BY canonical_position LIMIT $4::bigint) w ON true WHERE o.operation_id=$1::bigint AND o.owner_epoch=$2::bigint
